SELECT data_rows.id, data_rows.should_delete, data_rows.tenant_id, data_rows.kind, data_rows.subtype, data_rows.mime_type, data_rows.size_bytes, data_rows.digest, data_rows.storage, data_rows.inline_body, data_rows.uri, data_rows.compression, data_rows.encryption_kms_key_id, data_rows.redaction_policy_version, data_rows.redacted, data_rows.created_at, data_rows.schema_ref FROM  (SELECT 0 AS should_delete, `id`, `tenant_id`, `kind`, `subtype`, `mime_type`, `size_bytes`, `digest`, `storage`, `inline_body`, `uri`, `compression`, `encryption_kms_key_id`, `redaction_policy_version`, `redacted`, `created_at`, `schema_ref` FROM call_payload)  data_rows